package io.knowledgebrain.space;
import java.time.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class LearningAuthorizationTest {
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 @Test void commonGuestRegisteredPrincipalsAndLiveRolesControlPrivateLearning(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var api=new LearningAuthorizationController(spaces,identity,"a".repeat(43));for(String kind:new String[]{"GUEST","REGISTERED"}){when(identity.resolve("b".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,kind,Instant.now().plusSeconds(60)));when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,"PERSONAL","PRIVATE","OWNER"));assertEquals(actor,api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"ROADMAP_WRITE"),request()).getBody().principalId());when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,"PERSONAL","PRIVATE","VIEWER"));assertEquals("ROADMAP_READ",api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"ROADMAP_READ"),request()).getBody().action());assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"ROADMAP_WRITE"),request()));}when(spaces.visible(space,actor)).thenReturn(null);assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"ROADMAP_READ"),request()));}
 @Test void internalCapabilityNeverAcceptsBrowserCookiesOrOtherDomainActions(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var api=new LearningAuthorizationController(spaces,identity,"a".repeat(43));var id=new UuidV7(Clock.systemUTC()).next();var cookie=request();cookie.addHeader("Cookie","__Host-brain_guest=anything");assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(id,"b".repeat(43),"ROADMAP_READ"),cookie));for(String action:new String[]{"CONCEPT_WRITE","NOTE_READ","BRAIN_SEARCH"})assertThrows(ResponseStatusException.class,()->api.authorize(new LearningAuthorizationController.Check(id,"b".repeat(43),action),request()));verifyNoInteractions(spaces,identity);}
}
